// Links and anchors: every local link and #anchor in the Markdown points at a
// file or heading that exists (remark-validate-links), and every path written
// in backticks exists (paths.ts). The pages are processed together, the way
// remark's command line does it (unified-engine), so links between pages and
// headings in other pages are checked too.
import { join, relative, resolve } from "node:path";
import { Writable } from "node:stream";
import { remark } from "remark";
import remarkFrontmatter from "remark-frontmatter";
import remarkGfm from "remark-gfm";
import remarkValidateLinks from "remark-validate-links";
import { engine } from "unified-engine";
import { remarkExistingPaths } from "./paths.js";
// Remark's own report is not printed: the problems are returned instead.
const silent = () => new Writable({
    write: (_chunk, _encoding, done) => {
        done();
    },
});
// The plugins, given to the engine (not to the processor) so
// remark-validate-links sees every page at once. unified-engine's types accept
// only plugins without required options, though it passes them at run time.
function pluginsFor(settings) {
    return [
        [remarkFrontmatter],
        [remarkGfm],
        // Links to pages on GitHub are not checked as local files.
        [remarkValidateLinks, { repository: false }],
        [remarkExistingPaths, settings],
    ];
}
export async function checkLinks(pages, settings) {
    if (pages.length === 0)
        return [];
    const files = await new Promise((done, fail) => {
        engine({
            processor: remark,
            cwd: settings.root,
            files: pages.map((page) => join(settings.root, page)),
            extensions: ["md"],
            plugins: pluginsFor(settings),
            detectConfig: false,
            detectIgnore: false,
            out: false,
            output: false,
            quiet: true,
            color: false,
            streamError: silent(),
        }, (error, _code, context) => {
            if (error)
                fail(error);
            else
                done(context?.files ?? []);
        });
    });
    return files.flatMap((file) => file.messages.map((message) => ({
        file: relative(settings.root, resolve(file.cwd, file.path)).replaceAll("\\", "/"),
        ...(message.line ? { line: message.line } : {}),
        message: message.reason,
    })));
}
